          <p>پہچانیں سب سے نیچے باس میں کون سا سُر ہے: <code>Bass: 1</code> (بنیادی)، <code>Bass: 3</code> (1st اُلٹاؤ)، <code>Bass: 5</code> (2nd اُلٹاؤ) یا <code>Bass: 7</code> (3rd اُلٹاؤ)۔</p>
