        <p><strong>بنیادی سُر</strong> کارڈ کی جڑ بجاتا ہے؛ غلطی کے بعد <strong>A/B موازنہ</strong> دونوں کارڈز ایک ہی جڑ پر آمنے سامنے بجاتا ہے اور انورژن میں <strong>باس نوٹ سنیں</strong> سب سے نچلا سُر الگ سناتا ہے۔ <strong>لوپ</strong>، <strong>صرف سنیں</strong> اور 4 سطحی <strong>زمرہ امتحان</strong> بھی موجود ہیں۔</p>
