function renderRhythmInstrumentsHTML_UR(filterCat = "all") {
  const list = filterCat === "all"
    ? RHYTHM_INSTRUMENTS_DATA_UR
    : RHYTHM_INSTRUMENTS_DATA_UR.filter(i => i.category === filterCat);

  const ensembleCard = filterCat === "all" ? `
    <div class="article-highlight-box" style="margin-bottom:0.2rem;">
      <h4>پرکشن ایک گروو میں جگہ کیسے بانٹتی ہے (فریکوئنسی تقسیم):</h4>
      <p style="font-size:0.78rem; color:var(--raccoon-dark); line-height:1.4;">
        ہر ساز اپنی صوتی گلی سنبھالتا ہے تاکہ گروو صاف رہے: نیچے <strong>کِک</strong>، درمیان میں کڑکتا <strong>اسنیئر</strong>، اور اوپر چمکتے <strong>ہائی ہیٹ اور شیکر</strong>۔
      </p>
      <div class="k-btn-row" style="margin-top:0.35rem;">
        <button class="btn-tool" data-play-rhythm="band-groove">▶ بینڈ گروو (کِک + اسنیئر + ہیٹ + شیکر)</button>
      </div>
    </div>
  ` : "";

  return ensembleCard + list.map(item => `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag ${item.tagClass}">${item.tag}</span>
        <span class="k-ratio-chip">${item.role.split(" (")[0]}</span>
      </div>
      <h4>${item.name}</h4>
      <p><strong>کردار:</strong> ${item.role}</p>
      <p>${item.desc}</p>
      ${item.rhythmKey ? `
        <div class="k-btn-row">
          <button class="btn-tool" data-play-rhythm="${item.rhythmKey}">▶ ${item.btnLabel}</button>
        </div>
      ` : ""}
    </article>
  `).join("");
}

function renderVocalsReferenceHTML_UR() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">انسانی آواز</span>
        <span class="k-ratio-chip">پہلا قدرتی ساز</span>
      </div>
      <h4>انسانی آواز کیسے پیدا ہوتی ہے</h4>
      <p>آپ کی آواز ایک زندہ ساز کے اندر تین میکانکی صوتی نظام سموئے رکھتی ہے۔ گٹار یا بانسری کے برعکس اس کا «جسم» ملی سیکنڈز میں شکل بدل لیتا ہے — اور بیک وقت پِچ، والیوم، رنگت اور الفاظ گھڑتا ہے۔</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>1. توانائی کا ماخذ (سانس اور سہارا)</strong>
          سانس اندر لیتے وقت <em>ڈایافرام</em> نرمی سے نیچے پھیلتا ہے۔ گاتے وقت گلا دبانے کے بجائے پیٹ اور پسلیوں کے پٹھے مستحکم ہوا کا دباؤ («Breath Support») برقرار رکھتے ہیں۔
        </div>
        <div class="physics-fact-item">
          <strong>2. مرتعش حصہ (حنجرہ اور ووکل فولڈز)</strong>
          گلے کے اندر دو لچکدار <em>ووکل فولڈز</em> کھنچے ہوتے ہیں۔ گزرتی ہوا انہیں فی سیکنڈ 100–1,000 بار کھولتی بند کرتی ہے (<em>برنولی اثر</em>)، جس سے اوورٹونز سے بھرپور خام گونج بنتی ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>3. گونج خانہ (حلق، منہ اور فارمنٹس)</strong>
          حلق، منہ اور ناک کی جوف اس گونج کو فلٹر کرتے ہیں۔ زبان، جبڑے اور ہونٹوں کی معمولی حرکت صوتی چوٹیوں (<em>Formants</em>) کو بدل دیتی ہے — یوں گول «او» چمکتے «اِی» میں بدل جاتا ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>4. گلوکار کا فارمنٹ (~3,000 Hz)</strong>
          تربیت یافتہ کلاسیکی گلوکار حلق کا نچلا حصہ کشادہ کر کے 2.8–3.2 kHz پر توانائی مرکوز کر لیتے ہیں — جہاں آرکسٹرا کمزور ہوتا ہے — یوں ایک آواز بغیر مائیک کے 80 سازوں پر چھا جاتی ہے!
        </div>
      </div>

      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C4,E4,G4,C5" data-dur="1.9" data-step="0">▶ کورس کارڈ سنیں</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">رجسٹرز اور تکنیکیں</span>
        <span class="k-ratio-chip">آواز کے رنگ</span>
      </div>
      <h4>ووکل رجسٹرز اور گلوکاری کی تکنیکیں</h4>
      <p>حنجرے کے کون سے پٹھے سرگرم ہیں اور آیا ووکل فولڈز کا پورا جسم لرز رہا ہے یا صرف باریک کنارے، اس سے آواز کا رنگ بالکل بدل جاتا ہے:</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>چیسٹ وائس (Modal Register, M1)</strong>
          ووکل فولڈز کا پورا پٹھا ساتھ تھرتھراتا ہے۔ گرم، بھاری اور مضبوط آواز دیتا ہے — ہماری عام بول چال اور نچلے/درمیانی سُروں کی طاقت۔
        </div>
        <div class="physics-fact-item">
          <strong>ہیڈ وائس اور فالسٹو (M2)</strong>
          ووکل فولڈز لمبے اور پتلے ہو کر صرف کناروں سے لرزتے ہیں، جس سے بانسری جیسی ہلکی، ہوا میں تیرتی آواز نکلتی ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>مکسڈ وائس (Mix Voice)</strong>
          رجسٹر کی درمیانی تبدیلی (<em>Passaggio</em>) پر ہموار پل بناتی ہے تاکہ نیچے سے اوپر تک آواز اچانک ٹوٹے بغیر جڑی رہے۔
        </div>
        <div class="physics-fact-item">
          <strong>بیلٹنگ (پاپ، تھیٹر، گاسپل)</strong>
          مضبوط سانس کے سہارے اور روشن حروفِ علت کے ساتھ چیسٹ جیسی بھرپور طاقت کو اونچے سُروں تک لے جاتی ہے — نڈر اور براہِ راست آواز۔
        </div>
        <div class="physics-fact-item">
          <strong>وائبراٹو (Vibrato)</strong>
          تقریباً 5–7 Hz پر سُر اور والیوم میں قدرتی، پرسکون تھرتھراہٹ جو طویل سُروں میں گرمائش اور نرمی گھولتی ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>اسکیٹ اور اوورٹون گلوکاری</strong>
          جاز <em>اسکیٹ</em> ردھمک ہجّوں سے سازوں کی نقل کرتا ہے، جبکہ <em>اوورٹون گلوکاری</em> میں زبان کی خاص شکل ایک ڈرون پر اوپر دو سُر ایک ساتھ سناتی ہے!
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">کورس ترتیب (SATB)</span>
        <span class="k-ratio-chip">حصے اور رینجز</span>
      </div>
      <h4>کورس کے اندر: SATB آوازیں اور رینجز</h4>
      <p>دنیا بھر کے مخلوط کورس <strong>SATB</strong> ترتیب اپناتے ہیں — چار مرکزی حصے اوپر سے نیچے ترتیب دیے جاتے ہیں۔ بڑے کورس اکثر ہر حصے کو دو میں بانٹ کر آٹھ حصے (<em>SSAATTBB</em>) بنا لیتے ہیں۔</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>سوپرانو (S) • رینج C4–C6</strong>
          سب سے اونچی نسوانی یا تیز آواز۔ عموماً مرکزی دھن، بالائی ہارمونی اور کرسٹل جیسی چمک سنبھالتی ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>آلٹو (A) • رینج F3–E5</strong>
          نچلی نسوانی آواز (یا کاؤنٹر ٹینر)۔ مرکزی دھن کے عین نیچے اندرونی گرمائش (تھرڈز، سیونتھس) فراہم کرتی ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>ٹینر (T) • رینج C3–A4</strong>
          اونچی مردانہ آواز (اکثر ٹریبل کلیف میں لکھی جاتی ہے مگر ایک آکٹیو نیچے بجتی ہے!)۔ بالائی و زیریں حصوں کو جوڑتی ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>باس (B) • رینج E2–E4</strong>
          سب سے گہری مردانہ آواز اور کورس کا صوتی لنگر۔ باس کارڈ کی جڑ قائم کرتا ہے — باس سُر میں جمتے ہی پورا کارڈ کھل اٹھتا ہے۔
        </div>
        <div class="physics-fact-item">
          <strong>میزو سوپرانو، بیریٹون اور کاؤنٹر ٹینر</strong>
          تین اہم درمیانی آوازیں: <em>میزو</em> (A3–A5)، <em>بیریٹون</em> (G2–G4، سب سے عام مردانہ رینج) اور <em>کاؤنٹر ٹینر</em>۔
        </div>
        <div class="physics-fact-item">
          <strong>دیگر گروپ فارمیٹس</strong>
          <em>SSAA</em> اور <em>TTBB</em> آوازوں کو قریبی گونج میں سمیٹتے ہیں، جبکہ جدید <em>a cappella</em> گروپس ڈرم کِٹ کی جگہ منہ سے بیٹ باکسنگ کرتے ہیں۔
        </div>
      </div>

      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="G4,B4,D5,G5" data-dur="0.95" data-step="320">▶ سوپرانو رینج</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="G3,Bb3,D4,F4" data-dur="0.95" data-step="320">▶ آلٹو رینج</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,E3,G3,B3" data-dur="0.95" data-step="320">▶ ٹینر رینج</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="E2,G2,B2,E3" data-dur="1.05" data-step="340">▶ باس بنیاد</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">سُر کا ملاپ اور سماعت</span>
        <span class="k-ratio-chip">خالص نسبت (Just Intonation)</span>
      </div>
      <h4>بغیر ساز کے کورس پیانو سے زیادہ خالص کیوں سنائی دے سکتا ہے</h4>
      <p>پیانو <strong>12-ٹون مساوی تقسیم</strong> پر ٹیون ہوتے ہیں: ان کے میجر تھرڈز تقریباً 14 سینٹ تیز ہوتے ہیں تاکہ بارہوں کلیدیں بج سکیں۔ گلوکار مقررہ فریٹس یا ہتھوڑیوں کے پابند نہیں ہوتے۔</p>
      <p>اکیلے گاتے وقت اچھا کورس فطری طور پر خالص <strong>فریکوئنسی نسبتوں</strong> (2:1 آکٹیو، 3:2 ففتھ، 5:4 میجر تھرڈ) پر آ کر ٹکتا ہے — صفر دھڑکن کے ساتھ تمام اوورٹونز جڑتے ہیں اور کارڈ یکدم روشن ہو اٹھتا ہے!</p>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,G3,E4,C5" data-dur="1.4" data-step="460">▶ ایک ایک آواز جوڑیں (باس ← سوپ)</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,G3,E4,C5" data-dur="2.4" data-step="0">▶ مکمل SATB کورس کارڈ</button>
        <button class="btn-tool" data-open-warmup="true">▶ 5 منٹ ووکل وارم اپ کھولیں</button>
      </div>
    </article>
  `;
}

