function renderModesReferenceHTML_UR(familyFilter = "all") {
  const list = familyFilter === "all"
    ? MODES_ENCYCLOPEDIA_UR
    : MODES_ENCYCLOPEDIA_UR.filter(m => m.family === familyFilter);

  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">بنیادی اصول</span>
        <span class="k-ratio-chip">نسبتی بمقابلہ متوازی</span>
      </div>
      <h4>موڈز (Modes) دراصل کیا ہوتے ہیں؟</h4>
      <p>
        <strong>موڈ</strong> تب بنتا ہے جب آپ عین وہی سات سُر رکھیں مگر کسی دوسرے سُر کو اپنا گھر یعنی <strong>ٹانک (سا)</strong> مان لیں۔ صرف سفید کنجیاں (C میجر) رکھیں اور ہر نیا نقطہ آغاز الگ مزاج بناتا ہے: <code>D</code> سے <em>ڈورین</em>، <code>E</code> سے <em>فریجین</em>، <code>F</code> سے <em>لِڈین</em>، <code>G</code> سے <em>مکسولیڈین</em>، <code>A</code> سے <em>ایولین</em> اور <code>B</code> سے <em>لوکرین</em>۔
      </p>
      <div class="k-compare-grid">
        <div class="k-compare-box is-sage">
          <h5>1. نسبتی (Relative — ایک ہی کنجیاں)</h5>
          <p>کی بورڈ پر مقام جاننے کے لیے آسان: «D ڈورین عین C میجر کی سفید کنجیاں استعمال کرتا ہے۔» مگر شروع میں کان C کو ہی گھر سمجھتا رہتا ہے۔</p>
        </div>
        <div class="k-compare-box is-peach">
          <h5>2. متوازی (Parallel — ایک ہی جڑ!)</h5>
          <p><strong>کان کی تربیت کی کنجی:</strong> ساتوں موڈز کو <code>C</code> ہی سے شروع کر کے سنیں! فوراً ایک خاص امتیازی سُر پورا مزاج کھول دیتا ہے (مثلاً <code>C → F#</code> = لِڈین، <code>C → Bb</code> = مکسولیڈین)۔</p>
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">موڈل چمک کا اسپیکٹرم</span>
        <span class="k-ratio-chip">روشن تا گہرا</span>
      </div>
      <h4>چمک کے مطابق ترتیب (سرکل آف ففتھس کے ساتھ)</h4>
      <p>
        1 سے 7 کے بجائے ساتوں موڈز کو روشن ترین سے گہرے ترین تک ترتیب دیں تو ہر قدم پر عین <strong>ایک سُر آدھا قدم نیچے</strong> اترتا ہے:
      </p>
      <div class="mode-spectrum-strip">
        <span class="mode-spec-chip is-bright">1. لِڈین (#4)</span>
        <span class="mode-spec-chip">2. آئیونین</span>
        <span class="mode-spec-chip">3. مکسولیڈین (b7)</span>
        <span class="mode-spec-chip">4. ڈورین (b3, b7)</span>
        <span class="mode-spec-chip">5. ایولین (+b6)</span>
        <span class="mode-spec-chip">6. فریجین (+b2)</span>
        <span class="mode-spec-chip is-dark">7. لوکرین (+b5)</span>
      </div>
    </article>

    <div class="k-filter-row" aria-label="موڈز فلٹر کریں">
      <button class="k-filter-pill ${familyFilter === "all" ? "active" : ""}" data-mfilter="all">تمام (${MODES_ENCYCLOPEDIA_UR.length})</button>
      <button class="k-filter-pill ${familyFilter === "major" ? "active" : ""}" data-mfilter="major">میجر خاندان (3)</button>
      <button class="k-filter-pill ${familyFilter === "minor" ? "active" : ""}" data-mfilter="minor">مائنر خاندان (4)</button>
      <button class="k-filter-pill ${familyFilter === "variant" ? "active" : ""}" data-mfilter="variant">مائنر اقسام (2)</button>
    </div>

    <div class="knowledge-list">
      ${list.map(m => `
        <article class="knowledge-card">
          <div class="k-card-top-row">
            <span class="k-card-tag ${m.family === "major" ? "tag-peach" : m.family === "minor" ? "tag-lilac" : "tag-sage"}">${m.familyLabel} • ${m.brightness}</span>
            <span class="k-ratio-chip">${m.formula}</span>
          </div>
          <h4>${m.name} (${m.rootLabel} پر مثال)</h4>
          <p class="k-char">${m.stammton}</p>
          <p><strong>امتیازی سُر:</strong> ${m.charNote}<br><strong>قدموں کا فارمولا:</strong> <code>${m.steps}</code></p>
          <p>${m.desc}</p>
          <p>${m.usage}</p>
          <div class="k-btn-row">
            <button class="btn-tool" data-play-mode-scale="${m.id}">▶ اسکیل (${m.rootLabel})</button>
            <button class="btn-tool" data-play-mode-vamp="${m.id}">▶ کارڈ لوپ: ${m.vamp}</button>
          </div>
        </article>
      `).join("")}
    </div>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">گیت نگاری اور موڈل ہارمونی</span>
        <span class="k-ratio-chip">مرکز قائم رکھنا</span>
      </div>
      <h4>موڈل موسیقی لکھتے ہوئے واپس میجر میں پھسلنے سے کیسے بچیں</h4>
      <ul class="k-physics-list">
        <li><strong>اصل کلید کے ٹرائی ٹون سے بچیں:</strong> سفید کنجیوں میں <code>F</code> اور <code>B</code> مل کر G7 کا ٹرائی ٹون بناتے ہیں جو کان کو واپس C کی طرف کھینچتا ہے۔ D ڈورین میں G7 → C بجانے سے گریز کریں۔</li>
        <li><strong>دو کارڈز کے موڈل لوپس استعمال کریں:</strong> طویل کارڈ سلسلوں کے بجائے ٹانک اور اس پڑوسی کارڈ پر جھولیں جو <strong>امتیازی سُر</strong> چمکائے (مثلاً C ڈورین میں <code>Cm – F</code> روشن <code>A</code> ابھارتا ہے)۔</li>
        <li><strong>باس ڈرون (تانپورہ انداز) قائم کریں:</strong> جڑ + ففتھ کا مستقل ڈرون بجانے سے موڈ کا گھر مضبوط رہتا ہے اور ہر امتیازی سُر چمک اٹھتا ہے۔</li>
      </ul>
    </article>
  `;
}

