function renderNotationReferenceHTML_UR() {
  const staffFn = typeof buildNotationKnowledgeStaffSVG === "function" ? buildNotationKnowledgeStaffSVG : null;
  const trebleAnchorSvg = staffFn ? staffFn("treble", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const bassAnchorSvg = staffFn ? staffFn("bass", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const altoAnchorSvg = staffFn ? staffFn("alto", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const ledgerSvg = staffFn ? staffFn("treble", [-6, -4, -2, 4, 10, 12, 14], { width: 340, showLabels: true, labelShort: true }) : "";
  const ledgerBassSvg = staffFn ? staffFn("bass", [-6, -4, -2, 4, 10, 12, 14], { width: 340, showLabels: true, labelShort: true }) : "";
  const accSvg = staffFn ? staffFn("treble", [
    { step: 1, accidental: 0 },
    { step: 1, accidental: 1 },
    { step: 2, accidental: -1 },
    { step: 6, accidental: 0 },
    { step: 6, accidental: -1 }
  ], { width: 320, showLabels: true, labelShort: true }) : "";
  const keySigSharpSvg = staffFn ? staffFn("treble", [
    { step: 1, accidental: 1 },
    { step: 5, accidental: 1 },
    { step: 1, accidental: 0 }
  ], { width: 300, keySignatureId: "D", showLabels: true, labelShort: true }) : "";
  const keySigFlatSvg = staffFn ? staffFn("treble", [
    { step: 4, accidental: -1 },
    { step: 7, accidental: -1 },
    { step: 2, accidental: 0 }
  ], { width: 300, keySignatureId: "Eb", showLabels: true, labelShort: true }) : "";

  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">1. پانچ لائنوں کا اسٹاف</span>
        <span class="k-ratio-chip">لائنیں اور خانے</span>
      </div>
      <h4>کاغذ پر سُر اور وقت کا نقشہ کیسے بنتا ہے</h4>
      <p>
        معیاری نوٹیشن ایک گراف کی طرح کام کرتی ہے: <strong>عمودی محور</strong> سُر کی بلندی دکھاتا ہے (اوپر = باریک/تیز سُر، نیچے = بھاری/باس سُر)، جبکہ <strong>افقی محور</strong> ہمیشہ <strong>بائیں سے دائیں</strong> وقت میں آگے بڑھتا ہے۔
      </p>
      <ul class="k-physics-list">
        <li><strong>ہمیشہ نیچے سے اوپر گنیں:</strong> ہر اسٹاف میں <strong>5 لائنیں</strong> (نیچے 1st، اوپر 5th) اور ان کے بیچ <strong>4 خانے</strong> ہوتے ہیں۔</li>
        <li><strong>لائن – خانہ – لائن کی باری:</strong> لائن سے ساتھ والے خانے (یا خانے سے لائن) پر جانے سے سُر عین <strong>ایک اسکیل قدم</strong> بدلتا ہے (<code>C → D → E → F → G → A → B</code>)۔</li>
        <li><strong>کلیف کی ضرورت کیوں ہے:</strong> اکیلی پانچ لکیروں کا کوئی نام نہیں ہوتا — کلیف ایک مخصوص لائن پر <em>ایک واضح نشانی سُر</em> طے کر دیتا ہے۔</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">2. تین مرکزی کلیفس (اور خاص کلیفس)</span>
        <span class="k-ratio-chip">ٹریبل • باس • آلٹو</span>
      </div>
      <h4>ایک ہی کی بورڈ کو دیکھنے کی تین کھڑکیاں</h4>
      <p>
        روشن نارنجی لائن ہر کلیف کے <strong>نشانی سُر</strong> کو اجاگر کرتی ہے۔ صرف اس ایک نشان کو یاد کر لیں تو باقی تمام لائنیں اور خانے فوراً سمجھ آ جائیں گے۔
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${trebleAnchorSvg}
          <h5>ٹریبل کلیف (G کلیف)</h5>
          <p>درمیانی گھومتا گھیرا <strong>نیچے سے 2nd لائن = مڈل C سے اوپر G4</strong> کو گھیرتا ہے۔ گلوکاری، وائلن، بانسری، گٹار اور پیانو کے دائیں ہاتھ کا معیار۔</p>
          <p><strong>یاد رکھنے کے حوالے (نیچے ← اوپر):</strong> لائنیں <em>E4 – G4 – B4 – D5 – F5</em>؛ خانے <em>F4 – A4 – C5 – E5</em> (FACE)۔</p>
          <button type="button" class="btn-tool" data-play-solo-note="G4">▶ لنگر G4 سنیں</button>
        </div>
        <div class="notation-knowledge-card">
          ${bassAnchorSvg}
          <h5>باس کلیف (F کلیف)</h5>
          <p>دونوں نقطے <strong>نیچے سے 4th لائن = F3</strong> کو درمیان میں رکھتے ہیں۔ پیانو کے بائیں ہاتھ، چیلّو، باس گٹار، ٹرامبون اور نچلی آوازوں کی بنیاد۔</p>
          <p><strong>یاد رکھنے کے حوالے (نیچے ← اوپر):</strong> لائنیں <em>G2 – B2 – D3 – F3 – A3</em>؛ خانے <em>A2 – C3 – E3 – G3</em>۔</p>
          <button type="button" class="btn-tool" data-play-solo-note="F3">▶ لنگر F3 سنیں</button>
        </div>
        <div class="notation-knowledge-card">
          ${altoAnchorSvg}
          <h5>آلٹو کلیف (3rd لائن C کلیف)</h5>
          <p>نشان کا مرکز عین <strong>3rd (درمیانی) لائن = مڈل C (C4)</strong> کی طرف اشارہ کرتا ہے۔ وائولا اور کلاسک آرکسٹرا اسکور کا بنیادی کلیف۔</p>
          <p><strong>توازن کی سہولت:</strong> چونکہ <code>C4</code> عین درمیان میں ہے، اوپر 4th اور 5th لائنوں پر <em>E4</em> و <em>G4</em> اور نیچے 2nd و 1st پر <em>A3</em> و <em>F3</em> آتے ہیں۔</p>
          <button type="button" class="btn-tool" data-play-solo-note="C4">▶ لنگر C4 سنیں</button>
        </div>
      </div>

      <div class="k-meta-box">
        <div><strong>ایک ہی مڈل C (C4) تینوں کلیفس کو جوڑتا ہے:</strong> <strong>ٹریبل</strong> میں یہ <em>نیچے</em> 1st لیجر لائن پر، <strong>آلٹو</strong> میں عین <em>درمیان (3rd لائن)</em> پر، اور <strong>باس</strong> میں <em>اوپر</em> 1st لیجر لائن پر ہوتا ہے!</div>
        <div><strong>خاص کلیفس:</strong> <strong>ٹینر کلیف</strong> C-کلیف کو 4th لائن پر لے جاتا ہے (اونچے چیلّو/ٹرامبون کے لیے)، اور آکٹیو کلیفس (<code>8vb</code> / <code>8va</code>) گٹار یا پِکولو کو بغیر اضافی لکیروں کے ایک آکٹیو منتقل کر دیتے ہیں۔</div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">3. 3 لیجر لائنز تک پڑھنا</span>
        <span class="k-ratio-chip">±3 لیجر لائنز</span>
      </div>
      <h4>اوپر اور نیچے آہستہ گننے کے بغیر تیزی سے پڑھنا</h4>
      <p>
        جب دھن 5th لائن سے اوپر یا 1st لائن سے نیچے نکل جائے تو صرف ان نوٹس پر چھوٹی افقی لکیریں یعنی <strong>لیجر لائنز</strong> بنائی جاتی ہیں۔ مشقوں میں دونوں طرف <strong>3 لیجر لائنز</strong> تک شامل ہیں — یعنی اصل ساز و پیانو شیٹس کا پورا عملی دائرہ۔
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${ledgerSvg}
          <h5>ٹریبل کلیف: ±3 لیجر لائنز</h5>
          <p>بائیں جانب: نیچے 3rd، 2nd اور 1st لیجر لائنیں (<code>F3 – A3 – C4</code>)؛ بیچ میں: <code>B4</code>؛ دائیں جانب: اوپر 1st، 2nd اور 3rd لیجر لائنیں (<code>A5 – C6 – E6</code>)۔</p>
        </div>
        <div class="notation-knowledge-card">
          ${ledgerBassSvg}
          <h5>باس کلیف: گہرا باس اور بالائی حصہ</h5>
          <p>اسٹاف کے نیچے 3 لیجر لائنیں <code>E2 – C2</code> سے گہرے <code>A1</code> تک جاتی ہیں، اور اوپر مڈل <code>C4</code> سے گزر کر <code>E4</code> اور <code>G4</code> تک کھلتی ہیں۔</p>
        </div>
      </div>
      <ul class="k-physics-list">
        <li><strong>اسٹاف سے باہر 2 نشانی «ستون» پکے کریں:</strong> نیچے 1st اور 2nd لیجر لائن (مثلاً ٹریبل میں <code>C4</code> و <code>A3</code>) ذہن میں جما لیں اور پڑوسی سُر فوراً پڑھیں۔</li>
        <li><strong>لائن سے لائن چھلانگ:</strong> ایک لیجر لائن سے اگلی لیجر لائن تک چھلانگ ہمیشہ ایک <strong>تھرڈ (3rd)</strong> کے برابر ہوتی ہے!</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">4. عارضی علامتیں اور تحریری نظام</span>
        <span class="k-ratio-chip">♯ • ♭ • B vs H</span>
      </div>
      <h4>کالی کنجیاں، این ہارمونکس اور عالمی بمقابلہ جرمن نظام</h4>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${accSvg}
          <div class="k-btn-row" style="margin-top:0.25rem;">
            <button type="button" class="btn-tool" data-play-solo-note="F4">▶ F4</button>
            <button type="button" class="btn-tool" data-play-solo-note="F#4">▶ F♯4 / G♭4</button>
            <button type="button" class="btn-tool" data-play-solo-note="Bb4">▶ B♭4</button>
          </div>
        </div>
        <div class="notation-knowledge-card">
          <ul class="k-physics-list">
            <li><strong>شارپ (<code>♯</code>):</strong> سُر کو ٹھیک <strong>1 سیمی ٹون اوپر</strong> (دائیں کنجی) اٹھاتا ہے۔ <code>F</code> سے <code>F♯</code> بنتا ہے۔</li>
            <li><strong>فلیٹ (<code>♭</code>):</strong> سُر کو ٹھیک <strong>1 سیمی ٹون نیچے</strong> (بائیں کنجی) لاتا ہے۔ <code>G</code> سے <code>G♭</code> بنتا ہے۔</li>
            <li><strong>این ہارمونک برابری:</strong> کی بورڈ پر <code>F♯</code> اور <code>G♭</code> بالکل ایک ہی کالی کنجی ہیں، مگر کاغذ پر تحریر ہارمونی کا رخ بتاتی ہے۔</li>
            <li><strong>جرمن بمقابلہ عالمی نظام:</strong> جرمن موسیقی میں سفید نوٹ <em>B</em> کو <strong>H</strong> اور <em>B♭</em> کو <strong>B</strong> لکھا جاتا ہے! آپ ترتیبات میں کسی بھی وقت دونوں میں سوئچ کر سکتے ہیں۔</li>
          </ul>
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. کلیدیں اور کی سگنیچرز (Key Signatures)</span>
        <span class="k-ratio-chip">عالمی ♯/♭ + ♮</span>
      </div>
      <h4>جب علامتیں پورے اسٹاف پر لاگو ہوں</h4>
      <p>
        ہر نوٹ سے پہلے بار بار <code>♯</code> یا <code>♭</code> لگانے کے بجائے کی سگنیچرز <strong>کلیف کے عین ساتھ</strong> آتی ہیں اور <strong>ہر آکٹیو</strong> میں ان تمام متعلقہ سُروں کو خودکار بدل دیتی ہیں، جب تک کوئی نیچرل علامت (<code>♮</code>) انہیں منسوخ نہ کرے۔
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${keySigSharpSvg}
          <h5>شارپ کلیدیں (ترتیب: F♯ – C♯ – G♯ – D♯ – A♯ – E♯)</h5>
          <p><strong>D میجر (2♯)</strong> میں ہر لکھا ہوا <code>F</code> دراصل <code>F♯</code> اور ہر <code>C</code> دراصل <code>C♯</code> بجتا ہے — صرف تیسرے نوٹ سے پہلے <code>♮</code> واپس سفید <code>F</code> لاتا ہے۔</p>
        </div>
        <div class="notation-knowledge-card">
          ${keySigFlatSvg}
          <h5>فلیٹ کلیدیں (ترتیب: B♭ – E♭ – A♭ – D♭ – G♭ – C♭)</h5>
          <p><strong>E♭ میجر (3♭)</strong> میں <code>B♭</code>، <code>E♭</code> اور <code>A♭</code> شروع ہی سے پورے اسٹاف پر نافذ رہتے ہیں جب تک <code>♮</code> انہیں بحال نہ کرے۔</p>
        </div>
      </div>
    </article>
  `;
}

function renderArrangingReferenceHTML_UR() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">1. ارینجنگ (ترتیبِ موسیقی) کیا ہے؟</span>
        <span class="k-ratio-chip">خاکہ ← مکمل شاہکار</span>
      </div>
      <h4>ایک سادہ دھن کو جاندار موسیقی کے منظرنامے میں بدلنے کا فن</h4>
      <p>
        اگر <strong>کمپوزیشن</strong> کسی گیت کا بنیادی نقشہ ہے (یعنی دھن، بنیادی کارڈز اور بول)، تو <strong>ارینجنگ (Arrangement)</strong> اس کی مکمل عمارت، روشنی اور رنگوں کی ترتیب ہے: <em>کون سا ساز کب، کس آکٹیو میں، کس ردھم، نرمی یا طاقت اور کس رنگ کے ساتھ بجے گا؟</em>
      </p>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>سازوں کا انتخاب (Instrumentation)</strong>
          یہ طے کرنا کہ کون سے ساز یا آوازیں مرکزی دھن، باس، ہارمونی اور ردھم سنبھالیں گی۔
        </div>
        <div class="physics-fact-item">
          <strong>ساخت اور جذباتی سفر (Form &amp; Arc)</strong>
          پرسکون آغاز (Intro) سے لے کر مصرعے، کورس (Chorus) اور اختتام تک جوش و جذبے کا سفر بنانا۔
        </div>
        <div class="physics-fact-item">
          <strong>رجسٹر اور وائسنگ (Voicing)</strong>
          گہرے باس سے لے کر چمکتی ہوئی اونچی تانوں تک سُروں کو اس طرح پھیلانا کہ ہر ساز صاف سنائی دے۔
        </div>
        <div class="physics-fact-item">
          <strong>مکالمہ اور وقفے (Dialogue &amp; Space)</strong>
          کب سب ایک ساتھ بجیں (<em>Tutti</em>)، کب گلوکار کے وقفے میں کوئی ساز جواب دے اور کب خاموشی اثر پیدا کرے۔
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">2. مقصد اور استعمال</span>
        <span class="k-ratio-chip">ارینجنگ کیوں کی جاتی ہے؟</span>
      </div>
      <h4>ارینجنگ کس کام آتی ہے اور اسے موسیقی میں کہاں استعمال کیا جاتا ہے؟</h4>
      <p>
        ایک ہی گیت اپنے انہی چار کارڈز کے ساتھ <strong>پیانو بیلڈ</strong>، <strong>فنک گروو</strong>، <strong>چار آوازوں کا کوائر</strong> یا <strong>فلمی آرکسٹرا</strong> بن سکتا ہے:
      </p>
      <ul class="article-steps-list">
        <li><strong>1. سننے والے کی توجہ مرکوز رکھنا:</strong> انسانی کان بیک وقت صرف <strong>2 سے 3 موسیقی کی تہوں</strong> پر شعوری توجہ دے سکتا ہے۔ اچھی ارینجنگ مرکزی دھن کے لیے جگہ صاف رکھتی ہے۔</li>
        <li><strong>2. جذبات اور انداز کو اجاگر کرنا:</strong> اسٹرنگز کے لمبے سُر وسعت اور نرمی دیتے ہیں، براس (Brass) توانائی بھرتے ہیں اور اکیلا گٹار قربت کا احساس دیتا ہے۔</li>
        <li><strong>3. کانوں کی تھکن روکنا:</strong> اگر تمام ساز پہلے سیکنڈ سے آخر تک مسلسل بجتے رہیں تو کان جلد تھک جاتے ہیں۔ تہوں کو مرحلہ وار جوڑنا اور کم کرنا دلچسپی برقرار رکھتا ہے۔</li>
        <li><strong>4. دستیاب سازوں کے مطابق ڈھالنا:</strong> چاہے اسکول بینڈ ہو، اسٹرنگ کوارٹیٹ، کوائر (SATB) یا سولو پیانو — ارینجنگ موسیقی کو موجودہ سازوں کی رینج کے مطابق ڈھالتی ہے۔</li>
        <li><strong>5. حصوں کو جوڑنا (Transitions):</strong> ڈرم فلز، باس لائنز اور وقفے گیت کے حصوں کو فطری طور پر جوڑتے ہیں۔</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">3. چار تہوں کا ماڈل</span>
        <span class="k-ratio-chip">کرداروں کی تقسیم</span>
      </div>
      <h4>ہر شفاف ارینجنگ کے 4 بنیادی ستون</h4>
      <ul class="k-physics-list">
        <li><strong>1. مرکزی آواز (Lead / Focus):</strong> گلوکار یا سولو ساز جو اصل کہانی سناتا ہے۔</li>
        <li><strong>2. بنیاد (Bass &amp; Groove):</strong> باس ہارمونی کی جڑ فراہم کرتا ہے اور ڈرمز/پرکشن نبض سنبھالتے ہیں۔</li>
        <li><strong>3. ہارمونی کی تہہ (Pad &amp; Comping):</strong> اسٹرنگز، کوائر یا گٹار/پیانو کے کارڈز جو درمیانی حصے میں گرمائش بھرتے ہیں۔</li>
        <li><strong>4. جوابی نغمے اور سجاوٹ (Countermelody &amp; Fills):</strong> چھوٹے خوبصورت جملے جو اس وقت آتے ہیں جب مرکزی دھن سانس لیتی ہے۔</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-sketch">▶ 1. سادہ خاکہ (صرف دھن اور باس)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-full-layers">▶ 2. مکمل 4 تہوں والی ارینجنگ</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">4. رجسٹر اور وائسنگ</span>
        <span class="k-ratio-chip">صفائی بمقابلہ گدلا پن</span>
      </div>
      <h4>کچھ ارینجمنٹس شیشے کی طرح صاف اور کچھ گدلی کیوں لگتی ہیں؟</h4>
      <ul class="k-physics-list">
        <li><strong>اوورٹونز کا اصول (نیچے کشادہ، اوپر قریب):</strong> <code>C3</code> سے نیچے تنگ تھرڈز (Thirds) آواز کو بھاری اور گدلا کر دیتے ہیں (<em>Low-Interval Limit</em>)۔ نچلے حصے میں صرف روٹ، ففتھ اور آکٹیو رکھیں اور رنگین سُروں کو اوپر رکھیں۔</li>
        <li><strong>تنگ بمقابلہ کھلی وائسنگ (Drop-2):</strong> اوپر سے دوسرے سُر کو ایک آکٹیو نیچے لانے سے کارڈ فوراً کشادہ اور خوبصورت ہو جاتا ہے۔</li>
        <li><strong>ردھم کا توازن:</strong> ایک ہی رجسٹر کے دو سازوں کو مختلف ردھم دیں (مثلاً لمبے اسٹرنگ نوٹس + گٹار کی مختصر ضربیں)۔</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-voicing-muddy">▶ گدلی آواز: باس میں تنگ سُر</button>
        <button type="button" class="btn-tool" data-play-custom="arr-voicing-open">▶ شفاف آواز: کھلی اسٹوڈیو وائسنگ</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. ڈائنامکس اور مکالمہ</span>
        <span class="k-ratio-chip">Call &amp; Response • Drop</span>
      </div>
      <h4>پورے گیت میں کشش کیسے برقرار رکھی جائے؟</h4>
      <ul class="article-steps-list">
        <li><strong>سوال و جواب (Call &amp; Response):</strong> جب مرکزی دھن رکتی ہے تو ساز اس خلا میں جواب دیتا ہے۔</li>
        <li><strong>مخالف سمت کی حرکت (Counterpoint):</strong> جب مرکزی دھن اوپر جائے تو ذیلی دھن نیچے آتی ہے تاکہ دونوں الگ سنائی دیں۔</li>
        <li><strong>خاموشی کی طاقت (“The Drop”):</strong> اچانک ایک بار کے لیے اکثر ساز ہٹا دینا پانچ نئے ساز جوڑنے سے زیادہ اثر چھوڑتا ہے۔</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-call-response">▶ Call &amp; Response (سوال و جواب)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-counterpoint">▶ مخالف سمت کی کاؤنٹرپوائنٹ</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">6. ری ہارمونائزیشن اور چیک لسٹ</span>
        <span class="k-ratio-chip">وہی سُر، نیا رنگ</span>
      </div>
      <h4>دھن بدلے بغیر پورا جذباتی ماحول بدلنا</h4>
      <p>
        <strong>ری ہارمونائزیشن (Reharmonization)</strong> میں دھن وہی رہتی ہے مگر نیچے کے کارڈز بدل دیے جاتے ہیں (مثلاً سادہ <code>C – G – C</code> کی جگہ <code>Fmaj7 – Fm6 – Am9</code>)۔
      </p>
      <div class="k-btn-row" style="margin-top:0.45rem;margin-bottom:0.65rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-reharm-plain">▶ سادہ کارڈز پر دھن (I–V–I)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-reharm-cinema">▶ وہی دھن سنیمائی ہارمونی کے ساتھ</button>
      </div>
      <div class="k-meta-box">
        <div><strong>اپنی ارینجنگ کے لیے 5 سوالات کی چیک لسٹ:</strong></div>
        <div>1. <strong>اس وقت مرکزِ نگاہ کون ہے؟</strong> ہر لمحے صرف ایک عنصر نمایاں ہونا چاہیے۔</div>
        <div>2. <strong>سانس لینے کی جگہیں کہاں ہیں؟</strong> فلز (Fills) کو مرکزی دھن کے وقفوں میں رکھیں۔</div>
        <div>3. <strong>کیا نچلی فریکوئنسی صاف ہے؟</strong> <code>C3</code> سے نیچے تنگ تھرڈز سے بچیں۔</div>
        <div>4. <strong>کیا مصرعے اور کورس کا فرق فوراً محسوس ہوتا ہے؟</strong> آکٹیو اور کثافت میں فرق رکھیں۔</div>
        <div>5. <strong>میوٹ ٹیسٹ (Mute Test):</strong> کسی ٹریک کو بند کر کے دیکھیں؛ اگر کمی محسوس نہ ہو تو اسے واضح کردار دیں یا ہٹا دیں!</div>
      </div>
      <div class="k-btn-row" style="margin-top:0.55rem;">
        <button type="button" class="btn-tool" data-jump-ref="ensembles">آرکسٹرا اور بینڈز کی طرف →</button>
        <button type="button" class="btn-tool" data-jump-ref="cadences">کیڈنسز اور ہارمونی کی طرف →</button>
        <button type="button" class="btn-tool" data-jump-ref="physics">فزکس اور اوورٹونز کی طرف →</button>
      </div>
    </article>
  `;
}

